11	/*!
12	 * \file mat_mul_nd2nz.h
13	 * \brief
14	 */
15	#ifndef __OP_KERNEL_MATMUL_V3_ND2NZ_H__
16	#define __OP_KERNEL_MATMUL_V3_ND2NZ_H__
17	
18	#include "ai_infra_matmul_nd2nz_util.h"
19	#include "ai_infra_matmul_nd2nz_kernel.h"
20	#include "batch_ai_infra_matmul_nd2nz.h"
21	
22	using namespace AscendC;
23	using namespace matmul;
24	#if defined(__CCE_KT_TEST__)
25	using namespace std;
26	#endif
27	
28	template <class T>
29	__aicore__ inline void CopyPadNd2Nz(const GlobalTensor<T>& dstGlobal, const GlobalTensor<T>& srcGlobal, uint32_t baseH,
30	    uint32_t baseW, uint32_t orgHeight, uint32_t orgWidth, LocalTensor<T> ubLocal1, LocalTensor<T> ubLocal2,
31	    uint8_t padH, uint8_t padW)
32	{
33	    uint64_t c0Size;
34	    GetSizeC0<T>(c0Size);
35	
36	    uint32_t width = baseW - padW;
37	    uint32_t height = baseH - padH;
38	
39	    // Process gm->ub
40	    uint16_t blockLen = width * sizeof(T);
41	    uint32_t srcStride = (orgWidth - width) * sizeof(T);
42	    uint32_t numIter = height / BLOCK_COUNT_MAX;
43	    for (uint32_t i = 0; i < numIter; i++) {
44	        DataCopyPad(ubLocal1[BLOCK_COUNT_MAX * i * baseW],
45	            srcGlobal[static_cast<uint64_t>(BLOCK_COUNT_MAX) * i * orgWidth],
46	            {BLOCK_COUNT_MAX, blockLen, srcStride, 0, 0}, {false, 0, padW, 0});
47	    }
48	    uint16_t blockCountTail = height % BLOCK_COUNT_MAX;
49	
50	    if (blockCountTail) {
51	        DataCopyPad(ubLocal1[BLOCK_COUNT_MAX * numIter * baseW],
52	            srcGlobal[static_cast<uint64_t>(BLOCK_COUNT_MAX) * numIter * orgWidth],
53	            {blockCountTail, blockLen, srcStride, 0, 0}, {false, 0, padW, 0});
54	    }
55	
56	    SetFlag<HardEvent::MTE2_V>(static_cast<event_t>(0));
57	    WaitFlag<HardEvent::MTE2_V>(static_cast<event_t>(0));
58	
59	    // padding
60	    if (padH) {
61	        Duplicate(ubLocal1[height * baseW], (T)0, padH * baseW);
62	        PipeBarrier<PIPE_V>();
63	    }
64	
65	    // Process ub->ub
66	    uint32_t nRepeat = SINGLE_COPY_SIZE / sizeof(T);
67	    uint16_t nRowBlock = baseW / c0Size;
68	    uint32_t numIterI = baseH / REPEAT_TIMES_MAX;
69	    uint32_t heightTail = baseH % REPEAT_TIMES_MAX;
70	    uint32_t numIterJ = baseW / nRepeat;
71	    uint32_t widthTail = baseW % nRepeat;
72	
73	    for (uint32_t i = 0; i < numIterI; i++) {
74	        for (uint32_t j = 0; j < numIterJ; j++) {
75	            Copy(ubLocal2[baseH * nRepeat * j + i * REPEAT_TIMES_MAX * c0Size],
76	                ubLocal1[nRepeat * j + i * REPEAT_TIMES_MAX * baseW], nRepeat, REPEAT_TIMES_MAX,
77	                {static_cast<uint16_t>(baseH), 1, 1, nRowBlock});
78	        }
79	        if (widthTail) {
80	            Copy(ubLocal2[baseH * nRepeat * numIterJ + i * REPEAT_TIMES_MAX * c0Size],
81	                ubLocal1[nRepeat * numIterJ + i * REPEAT_TIMES_MAX * baseW], widthTail, REPEAT_TIMES_MAX,
82	                {static_cast<uint16_t>(baseH), 1, 1, nRowBlock});
83	        }
84	    }
85	    if (heightTail){
86	        for (uint32_t j = 0; j < numIterJ; j++) {
87	            Copy(ubLocal2[baseH * nRepeat * j + numIterI * REPEAT_TIMES_MAX * c0Size],
88	                ubLocal1[nRepeat * j + numIterI * REPEAT_TIMES_MAX * baseW], nRepeat, heightTail,
89	                {static_cast<uint16_t>(baseH), 1, 1, nRowBlock});
90	        }
91	        if (widthTail) {
92	            Copy(ubLocal2[baseH * nRepeat * numIterJ + numIterI * REPEAT_TIMES_MAX * c0Size],
93	                ubLocal1[nRepeat * numIterJ + numIterI * REPEAT_TIMES_MAX * baseW], widthTail, heightTail,
94	                {static_cast<uint16_t>(baseH), 1, 1, nRowBlock});
95	        }
96	    }
97	    
98	    SetFlag<HardEvent::V_MTE3>(static_cast<event_t>(0));
99	    WaitFlag<HardEvent::V_MTE3>(static_cast<event_t>(0));
100	
101	    uint64_t orgHeightRound = MMV3DivCeil(orgHeight, ALIGNED_H) * ALIGNED_H;
102	    // Process ub->gm
103	    if (orgHeightRound - baseH <= UINT16_MAX) {
104	        DataCopy(dstGlobal, ubLocal2, {nRowBlock, static_cast<uint16_t>(baseH), 0, uint16_t(orgHeightRound - baseH)});
105	    } else {
106	        for (uint16_t i = 0; i < nRowBlock; i++) {
107	            DataCopy(dstGlobal[orgHeightRound * c0Size * i], ubLocal2[baseH * c0Size * i],
108	                {1, static_cast<uint16_t>(baseH), 0, 0});
109	        }
110	    }
111	}
112	
113	#if defined(__CCE_AICORE__) && (__CCE_AICORE__ > 200)
114	template <>
115	__aicore__ inline void CopyPadNd2Nz<bfloat16_t>(const GlobalTensor<bfloat16_t>& dstGlobal,
116	                                                 const GlobalTensor<bfloat16_t>& srcGlobal,
117	    uint32_t baseH, uint32_t baseW, uint32_t orgHeight, uint32_t orgWidth, LocalTensor<bfloat16_t> ubLocal1,
118	    LocalTensor<bfloat16_t> ubLocal2, uint8_t padH, uint8_t padW)
119	{
120	    GlobalTensor<half> dstGlobalTrans;
121	    GlobalTensor<half> srcGlobalTrans;
122	    dstGlobalTrans.SetGlobalBuffer((__gm__ half*)dstGlobal.GetPhyAddr(0));
123	    srcGlobalTrans.SetGlobalBuffer((__gm__ half*)srcGlobal.GetPhyAddr(0));
124	    CopyPadNd2Nz<half>(dstGlobalTrans, srcGlobalTrans, baseH, baseW, orgHeight, orgWidth,
125	                       ubLocal1.ReinterpretCast<half>(), ubLocal2.ReinterpretCast<half>(), padH, padW);
126	}
127	#endif
128	
129	#if defined(__DAV_C220_VEC__)
130	template <class T, Nd2NzMode mode = Nd2NzMode::MULTI_CORE>
131	__aicore__ inline bool Nd2nzVnchwMM(GlobalTensor<T>& dst, GlobalTensor<T>& src, uint32_t height, uint32_t width,
132	                                    uint32_t batch, TBuf<TPosition::VECCALC>& ubBuffer, uint32_t usedCoreNum) {
133	    KernelND2NZMM<T> op;
134	    op.Init((GM_ADDR)dst[0].GetPhyAddr(), (GM_ADDR)src[0].GetPhyAddr(), height, width, batch, ubBuffer, usedCoreNum);
135	    return op.template ProcessMM<mode>();
136	}
