163	        uint64_t dCnt = MMV3DivCeil(dValue, baseD);
164	        uint64_t nBaseTil = nValue - (nCnt - 1) * baseN;   // n方向上的baseN尾块
165	        uint64_t dBaseTail = dValue - (dCnt - 1) * baseD;  // m方向上的baseM尾块
166	        uint64_t totalCnt = nCnt * dCnt;
167	        uint32_t round = (totalCnt + usedCoreNum - 1) / usedCoreNum;  // 每一个core最大做base块计算的次数
168	        uint32_t realRound = 0;                                       // 单核做多少次base块计算
169	        uint32_t preCoreNum = totalCnt % usedCoreNum;  // 从0core开始有多少个core会多做一次base块
170	        uint32_t preTotalBlock = 0;
171	        uint32_t index = 0;  // 当前block_idx的起始基本块Index，按先循环D再循环N的次序
172	        if (preCoreNum == 0) {
173	            preCoreNum = usedCoreNum;
174	        }
175	        // ND
176	        if (vBlockIndex < preCoreNum) {
177	            index = vBlockIndex * round;
178	            // 前面preCoreNum个core会多做一次
179	            realRound = round;
180	        } else {
181	            index = vBlockIndex * (round - 1) + preCoreNum;
182	            // 后面的core会少做一次
183	            realRound = round - 1;
184	        }
185	        uint32_t nCalcLen = 0;
186	        uint32_t dCalcLen = 0;
187	        uint32_t padN = 0;
188	        uint32_t padD = 0;
189	        uint32_t nIndx = 0;
190	        uint32_t dIndx = 0;
191	        uint32_t lastD = oriD % baseD;
192	        for (uint32_t j = 0; j < realRound; ++j) {
193	            if (index < totalCnt) {
194	                if ((index + 1) % (nCnt * dCnt) == 0) {
195	                    // 最后一块是尾块
196	                    nCalcLen = nBaseTil;
197	                    dCalcLen = dBaseTail;
198	                } else if ((index + 1) % (nCnt * dCnt) > (nCnt - 1) * dCnt) {
199	                    // n方向尾块
200	                    nCalcLen = nBaseTil;
201	                    dCalcLen = baseD;
202	                } else if ((index + 1) % dCnt == 0) {
