216	            padD = (dIndx == dCnt - 1) ? dValue - oriD : 0;  // will be used ???
217	            auto srcGmIdx = (dIndx * baseD + nIndx * baseN * oriD);
218	            auto dstGmIdx = (dIndx * nValue * baseD + nIndx * baseN * c0Size);
219	            CopyPadNd2Nz(tempDstGlobal[dstGmIdx], tempSrcGlobal[srcGmIdx], nCalcLen, dCalcLen, oriN, oriD, tempUb,
